    // Place names: the known Japanese form (curated here, then data/names-ja.json from GeoNames and Natural Earth),
    // else a katakana reading. Only for names the app knows are places (regions, candidates' towns, fires).
  // Katakana for a place name with no known Japanese form: a phonetic reading of the letters (a fallback, not a translation)
  var KV={a:0,i:1,u:2,e:3,o:4};
  var KT={'':'アイウエオ',k:'カキクケコ',g:'ガギグゲゴ',s:'サシスセソ',z:'ザジズゼゾ',t:'タティトゥテト',d:'ダディドゥデド',n:'ナニヌネノ',h:'ハヒフヘホ',b:'バビブベボ',p:'パピプペポ',m:'マミムメモ',y:'ヤイユイェヨ',r:'ラリルレロ',w:'ワウィウウェウォ',f:'ファフィフフェフォ',v:'ヴァヴィヴヴェヴォ',j:'ジャジジュジェジョ',ch:'チャチチュチェチョ',sh:'シャシシュシェショ',ts:'ツァツィツツェツォ',ny:'ニャニニュニェニョ',ky:'キャキキュキェキョ'};
  function kCell(c,v){var row=KT[c];if(row==null)row=KT[''];
    // rows with 2-char cells
    if(row.length>5){var cells=row.match(/[ァ-ヴー][ァィゥェォャュョ]?/g);return cells[KV[v]];}
    return row.charAt(KV[v]);}
  function kana(word){
    var w=word.normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z]/g,'');if(!w)return word;
    w=w.replace(/ph/g,'f').replace(/ck/g,'k').replace(/qu(?=[ei])/g,'k').replace(/qu/g,'kw').replace(/gu(?=[ei])/g,'g').replace(/nh/g,'ny').replace(/lh/g,'ry').replace(/ll/g,'l').replace(/th/g,'s')
      .replace(/c(?=[eiy])/g,'s').replace(/c(?!h)/g,'k').replace(/x/g,'ks').replace(/l/g,'r').replace(/q/g,'k').replace(/g(?=[ei])/g,'j').replace(/(.)\1/g,'$1');
    if(w.length>3)w=w.replace(/([^aeiou])e$/,'$1');                 // silent final e (Riverside, Butte)
    w=w.replace(/y(?=[^aeiou]|$)/g,'i');
    var out='',i=0;
    while(i<w.length){
      var c='';var two=w.substr(i,2);
      if(two==='ch'||two==='sh'||two==='ts'||two==='ny'){c=two;i+=2;}
      else if(!/[aeiou]/.test(w[i])){c=w[i];i++;}
      if(i<w.length&&/[aeiou]/.test(w[i])){var v=w[i];i++;
        if(c==='')out+=kCell('',v);else out+=kCell(c,v);
        if(i<w.length&&w[i]===v)i++;                                // long vowel: once is enough
      }else{
        if(c==='n')out+='ン';else if(c==='m')out+=(/[bp]/.test(w[i]||'')?'ン':'ム');
        else if(c==='t'||c==='d')out+=kCell(c,'o');else if(c==='ch'||c==='sh'||c==='j')out+=kCell(c,'i');
        else if(c)out+=kCell(c,'u');
      }
    }
    return out;
  }
  window.__wfKana=function(name){return String(name).split(/(\s+|-)/).map(function(p){return /^\s+$|^-$/.test(p)?'・':(/[a-zà-ÿ]/i.test(p)?kana(p):p);}).join('').replace(/・+/g,'・');};

